import * as T from './vendor/three.module.js';
import {OrbitControls} from './vendor/OrbitControls.js';
import {SelectionGesture} from './selection-gesture.js';
import {geographyAssets} from './geography-assets.js';
import {explorerModel,projectedPolygons,projectPoint,segmentColor,categoryLabels,monitoredStates,isKeySeat,historicalComposition} from './election-explorer.js';
import {ratingForSeat} from './seat-outlook.js';

async function geography(key){const item=geographyAssets[key],response=await fetch(item.path);if(!response.ok)throw Error('Map unavailable');const bytes=await response.arrayBuffer(),hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');if(hash!==item.sha256||bytes.byteLength!==item.bytes)throw Error('Map verification failed');return JSON.parse(new TextDecoder().decode(bytes));}
const ratingText=r=>({'solid-D':'民主党稳固','likely-D':'民主党优势','lean-D':'倾向民主党','tossup':'竞争胶着','lean-R':'倾向共和党','likely-R':'共和党优势','solid-R':'共和党稳固'}[r?.rating]||'未知评级');
const seatId=f=>'H-'+f.properties.postal+'-'+f.properties.district;
function stripeTexture(segments,dim=false){const canvas=document.createElement('canvas');canvas.width=512;canvas.height=32;const c=canvas.getContext('2d'),total=segments.reduce((n,s)=>n+s.count,0)||1;let x=0;for(const s of segments){const width=s.count/total*512;c.fillStyle=segmentColor(s);c.fillRect(x,0,width+1,32);if(s.kind==='lean'||s.kind==='unknown'){c.save();c.beginPath();c.rect(x,0,width,32);c.clip();c.strokeStyle=s.kind==='unknown'?'#8998aa88':'#ffffff88';c.lineWidth=3;for(let a=x-32;a<x+width+32;a+=12){c.beginPath();c.moveTo(a,32);c.lineTo(a+32,0);c.stroke();}c.restore();}if(s.independent){c.strokeStyle='#b35bff';c.lineWidth=5;c.strokeRect(x+2,2,width-4,28);}x+=width;}if(dim){c.fillStyle='#07152799';c.fillRect(0,0,512,32);}const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;return texture;}
function shapesFor(feature){return projectedPolygons(feature).map(rings=>{const shape=new T.Shape(rings[0].map(([x,z])=>new T.Vector2(x,-z)));for(const ring of rings.slice(1))shape.holes.push(new T.Path(ring.map(([x,z])=>new T.Vector2(x,-z))));return shape;});}
function disposeTree(root){const geometries=new Set(),materials=new Set();root.traverse(o=>{if(o.geometry)geometries.add(o.geometry);if(o.material)(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>materials.add(m));});geometries.forEach(g=>g.dispose());materials.forEach(m=>{m.map?.dispose();m.dispose();});}
function labelSprite(text,star='',compact=false){const canvas=document.createElement('canvas');canvas.width=compact?64:128;canvas.height=64;const c=canvas.getContext('2d');c.fillStyle='#112e4a';c.beginPath();c.roundRect(2,2,canvas.width-4,60,12);c.fill();c.fillStyle='#fff';c.font=compact?'700 48px system-ui':'700 28px system-ui';c.textAlign='center';c.fillText(compact?star:(star?star+' ':'')+text,canvas.width/2,compact?49:42);const sprite=new T.Sprite(new T.SpriteMaterial({map:new T.CanvasTexture(canvas),depthTest:false,transparent:true,sizeAttenuation:!compact}));sprite.userData.screenSize=compact;sprite.userData.labelSize=compact?[.018,.018]:star?[1.4,.7]:[1.05,.525];sprite.scale.set(...sprite.userData.labelSize,1);return sprite;}

export async function createStateMap(host,{roster,evidence,chamber:initialChamber,onSeat,esc}){
 const [states,districts]=await Promise.all([geography('states20m'),geography('districts7')]);
 if(states.features.length!==50||new Set(states.features.map(f=>f.properties.postal)).size!==50)throw Error('Expected 50 states');
 let baseMode='historical',chamber=initialChamber,selectedState=null,keyOnly=false,renderer=null,camera=null,controls=null,scene=null,world=null,picks=[],districtLayer=null,cameraGoal=null,hovered=null,visible=true;
 host.innerHTML=`<div class="map-toolbar"><label>选择州 <select id="map-state"><option value="">全美</option>${states.features.map(f=>`<option value="${f.properties.postal}">${f.properties.postal} · ${esc(f.properties.name)}</option>`).join('')}</select></label><label>底层 <select id="map-baseline"><option value="historical">2024选后基线</option><option value="current">当前党团</option></select></label><div><button id="map-reset">全美</button><button id="map-top">俯瞰</button><button id="map-plus" aria-label="放大">＋</button><button id="map-minus" aria-label="缩小">−</button></div></div><div class="map-key"><span><i class="map-shadow-key"></i><span id="map-base-label">2024选后基线 · 底层</span></span><span><i class="map-bright-key"></i>2026评级 · 上层</span><span>★ 竞争席所在州 · ☆ 监测重点</span></div><div class="map-layout"><div id="state-map-canvas" aria-label="美国50州三维席位地图"></div><aside id="map-detail"></aside></div><details class="source-details map-sources"><summary>地图与统计来源</summary><p>州色带表示州内席位构成，不代表全州单一赢家或选区位置；具体数量见州详情。</p><p>参院保留席与改选席分列；未知评级不作为平手。</p><p>州界：U.S. Census Bureau · 2025 · AK/HI为缩放插图。</p><p>选区几何仅覆盖7个已核验2026选区，其余使用列表；2024结果不套用到重划后的2026边界。</p><a href="geography/state-sources.json">州界来源</a> · <a href="geography/district-sources.json">选区来源</a> · <a href="geography/boundary-status.json">区划版本</a></details>`;
 const canvas=host.querySelector('#state-map-canvas'),detail=host.querySelector('#map-detail'),select=host.querySelector('#map-state');
 const watchStates=()=>chamber==='senate'?monitoredStates:['AZ','CA','CO','MI','NJ','NY','PA'];
 const baseLabel=()=>baseMode==='historical'?'2024选后基线 · 党籍':'当前党团';
 const baseline=state=>baseMode==='historical'?historicalComposition(evidence,chamber,state):explorerModel(roster,evidence,chamber,state).current;
 const section=(group,total)=>`<div class="seat-track">${group.segments.map(s=>`<span class="seat-segment side-${s.alignment} kind-${s.kind}${s.independent?' is-independent':''}" style="flex-basis:${s.count/total*100}%" title="${s.alignment} · ${esc(categoryLabels[s.kind])} ${s.count}"></span>`).join('')}</div><div class="map-counts">${group.segments.map(s=>`<span><i style="background:${segmentColor(s)}"></i>${s.alignment==='T'||s.alignment==='U'?'':s.alignment+' · '}${esc(categoryLabels[s.kind])}${s.independent?' · 独立议员':''} <b>${s.count}</b></span>`).join('')}</div>`;
 function describe(state){const model=explorerModel(roster,evidence,chamber,state),feature=states.features.find(f=>f.properties.postal===state);detail.innerHTML=`<h3>${state?esc(feature.properties.name):'全美'}${state?(model.keySeats.length?' ★':watchStates().includes(state)?' ☆':''):''}</h3><div class="map-state-totals"><span>全部席位 <b>${model.capacity}</b></span><span>关键席位 <b>${model.keySeats.length}</b></span></div><h4>${esc(baseLabel())}</h4>${section(baseline(state),model.capacity)}<h4>2026逐席评级</h4>${section(model.outlook,model.capacity)}${state?`<h4>州内席位</h4><div class="map-seat-list">${model.seats.filter(s=>!keyOnly||isKeySeat(s,evidence)).map(s=>{const r=ratingForSeat(s,evidence),geometry=districts.features.find(f=>seatId(f)===s.seatId);return `<div><button data-map-seat="${esc(s.seatId)}">${esc(s.seatId)} · ${s.contested2026?esc(ratingText(r)):'不改选基础'}${s.special?' · 特别选举':''}</button>${geometry?`<button data-district="${esc(s.seatId)}">2026区界 ↗</button>`:''}</div>`;}).join('')}</div>`:'<p>选择州查看席位</p>'}<details class="source-details"><summary>来源详情</summary><p>当前党籍：D ${model.party.D} · R ${model.party.R} · I ${model.party.I} · 空缺 ${model.party.vacant}</p><p>不改选基础 ${model.retained} · 已映射评级 ${model.mapped} / ${model.contested}</p><p>历史基线按最近一次选举结果的党籍，独立议员不推定党团；2026评级保留独立身份标记。</p><p>参院基线包括2020年31席、2022年35席和2024年34席；不是100席均在2024年改选，也不是当日任职名册。</p><p>${esc(roster.asOf)}</p>${(historicalComposition(evidence,chamber,state)?.sources||[]).map(source=>`<a href="${esc(source.url)}" target="_blank" rel="noopener">历史结果来源 ↗</a>`).join(' · ')}${[...new Set(model.seats.map(s=>ratingForSeat(s,evidence)?.source).filter(Boolean))].map(url=>`<a href="${esc(url)}" target="_blank" rel="noopener">评级原文 ↗</a>`).join(' · ')}</details>`;detail.querySelectorAll('[data-map-seat]').forEach(b=>b.onclick=()=>onSeat(roster.seats.find(s=>s.seatId===b.dataset.mapSeat)));detail.querySelectorAll('[data-district]').forEach(b=>b.onclick=()=>focusDistrict(b.dataset.district));}
 function draw(){if(!renderer)return;if(world){scene.remove(world);disposeTree(world);}world=new T.Group();scene.add(world);picks=[];
  for(const f of states.features){const state=f.properties.postal,m=explorerModel(roster,evidence,chamber,state),geometry=new T.ExtrudeGeometry(shapesFor(f),{depth:.22,bevelEnabled:false,curveSegments:1});geometry.computeBoundingBox();const bounds=geometry.boundingBox,width=bounds.max.x-bounds.min.x;const uv=geometry.getAttribute('uv'),pos=geometry.getAttribute('position');for(let i=0;i<uv.count;i++)uv.setXY(i,(pos.getX(i)-bounds.min.x)/width,.5);uv.needsUpdate=true;
   const group=new T.Group(),side=new T.MeshStandardMaterial({color:0x263e57,metalness:.4,roughness:.5}),top=new T.MeshStandardMaterial({map:stripeTexture(m.outlook.segments),roughness:.45,metalness:.14}),base=new T.MeshStandardMaterial({map:stripeTexture(baseline(state).segments,true),roughness:.75});
   const shadow=new T.Mesh(geometry,[base,side]);shadow.rotation.x=-Math.PI/2;shadow.position.set(.08,.06,.11);shadow.castShadow=true;group.add(shadow);const face=new T.Mesh(geometry,[top,side]);face.rotation.x=-Math.PI/2;face.position.y=.46;face.castShadow=true;face.receiveShadow=true;face.userData.state=state;group.add(face);picks.push(face);
   const line=new T.LineSegments(new T.EdgesGeometry(geometry,45),new T.LineBasicMaterial({color:selectedState===state?0xffe2a0:0xd4e1ef,transparent:true,opacity:.7}));line.rotation.copy(face.rotation);line.position.copy(face.position);group.add(line);
   if(keyOnly&&!m.keySeats.length)group.traverse(o=>{if(o.material)for(const material of Array.isArray(o.material)?o.material:[o.material]){material.transparent=true;material.opacity=.2;}});
   const box=new T.Box3().setFromObject(face),center=box.getCenter(new T.Vector3()),size=box.getSize(new T.Vector3());group.userData={state,center,size,line,face};group.position.y=state===selectedState?.16:0;
   if(m.keySeats.length||watchStates().includes(state)||state===selectedState||((canvas.clientWidth>=500||['AK','HI'].includes(state))&&Math.max(size.x,size.z)>1.1)){const label=labelSprite(state,m.keySeats.length?'★':watchStates().includes(state)?'☆':'',canvas.clientWidth<500&&state!==selectedState&&(m.keySeats.length>0||watchStates().includes(state)));label.position.set(center.x,.94,center.z);group.add(label);}world.add(group);
  }canvas.dataset.states=50;canvas.dataset.chamber=chamber;canvas.dataset.scope=keyOnly?'key':'all';showDistricts();
 }
 function selectState(state,zoom=true){selectedState=state||null;select.value=selectedState||'';describe(selectedState);draw();if(zoom&&renderer){const g=world.children.find(g=>g.userData.state===state);if(g){const distance=Math.max(5,Math.max(g.userData.size.x,g.userData.size.z)*2.3)*Math.max(1,1/camera.aspect);cameraGoal={target:g.userData.center.clone(),pos:g.userData.center.clone().add(new T.Vector3(0,distance,distance*.65))};}else reset();}canvas.dataset.selectedState=selectedState||'';delete canvas.dataset.selectedDistrict;}
 function showDistricts(){if(districtLayer){scene.remove(districtLayer);disposeTree(districtLayer);}districtLayer=new T.Group();scene.add(districtLayer);if(chamber!=='house'||!selectedState)return;for(const f of districts.features.filter(f=>f.properties.postal===selectedState)){const seat=roster.seats.find(s=>s.seatId===seatId(f));if(!seat)continue;const m=explorerModel({seats:[seat]},evidence,'house'),geo=new T.ExtrudeGeometry(shapesFor(f),{depth:.025,bevelEnabled:false,curveSegments:1}),mesh=new T.Mesh(geo,new T.MeshStandardMaterial({color:segmentColor(m.outlook.segments[0]),roughness:.35,emissive:0x3a6fa8,emissiveIntensity:.25}));mesh.rotation.x=-Math.PI/2;mesh.position.y=.92;mesh.userData.districtSeat=seat.seatId;districtLayer.add(mesh);const edges=new T.LineSegments(new T.EdgesGeometry(geo),new T.LineBasicMaterial({color:0xffd33e}));edges.rotation.copy(mesh.rotation);edges.position.y=.96;districtLayer.add(edges);}canvas.dataset.districts=districtLayer.children.length/2;}
 function focusDistrict(id){const f=districts.features.find(f=>seatId(f)===id);if(!f||!renderer)return;const [x,z]=projectPoint(...f.properties.label_point,f.properties.postal);cameraGoal={target:new T.Vector3(x,.6,z),pos:new T.Vector3(x,5,z+3.2)};canvas.dataset.selectedDistrict=id;for(const group of world.children){for(const material of group.userData.face.material){material.transparent=true;material.opacity=.25;}for(const child of group.children)if(child.isSprite)child.visible=false;}const label=labelSprite(f.properties.postal+'-'+f.properties.district);label.position.set(x,1.2,z);districtLayer.add(label);}
 function reset(){if(!renderer)return;const box=new T.Box3().setFromObject(world),center=box.getCenter(new T.Vector3()),direction=new T.Vector3(0,.85,.65).normalize(),up=new T.Vector3(0,direction.z,-direction.y),tan=Math.tan(camera.fov*Math.PI/360);let distance=0;for(const x of [box.min.x,box.max.x])for(const y of [box.min.y,box.max.y])for(const z of [box.min.z,box.max.z]){const corner=new T.Vector3(x,y,z).sub(center),depth=corner.dot(direction);distance=Math.max(distance,Math.abs(corner.x)/(tan*camera.aspect)+depth,Math.abs(corner.dot(up))/tan+depth);}cameraGoal={target:center,pos:center.clone().addScaledVector(direction,distance*1.07)};}
 try{renderer=new T.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;canvas.appendChild(renderer.domElement);canvas.dataset.renderer='three-webgl';scene=new T.Scene();scene.background=new T.Color(0x0c1d31);camera=new T.PerspectiveCamera(38,1,.1,250);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.enablePan=true;controls.minPolarAngle=.05;controls.maxPolarAngle=1.25;controls.minDistance=3;controls.maxDistance=100;controls.addEventListener('start',()=>cameraGoal=null);scene.add(new T.HemisphereLight(0xcce3ff,0x122033,2.4));const light=new T.DirectionalLight(0xfff1d9,2.2);light.position.set(-12,24,18);light.castShadow=true;light.shadow.mapSize.set(2048,2048);Object.assign(light.shadow.camera,{left:-26,right:26,top:22,bottom:-22,far:90});light.shadow.bias=-.001;scene.add(light);const floor=new T.Mesh(new T.PlaneGeometry(64,38),new T.MeshStandardMaterial({color:0x132c43,roughness:.85}));floor.rotation.x=-Math.PI/2;floor.position.y=-.04;floor.receiveShadow=true;scene.add(floor);
 const gesture=new SelectionGesture();renderer.domElement.addEventListener('pointerdown',e=>{if(e.button===0)gesture.start(e.pointerId,e.clientX,e.clientY);});renderer.domElement.addEventListener('pointermove',e=>gesture.move(e.pointerId,e.clientX,e.clientY));renderer.domElement.addEventListener('pointercancel',e=>gesture.cancel(e.pointerId));const tooltip=document.createElement('div');tooltip.className='map-tooltip';tooltip.hidden=true;canvas.append(tooltip);renderer.domElement.addEventListener('pointermove',e=>{if(e.buttons||e.pointerType!=='mouse'){tooltip.hidden=true;return;}const rect=canvas.getBoundingClientRect(),ray=new T.Raycaster();ray.setFromCamera(new T.Vector2((e.clientX-rect.left)/rect.width*2-1,1-(e.clientY-rect.top)/rect.height*2),camera);const hit=ray.intersectObjects(picks)[0],state=hit?.object.userData.state;if(hovered!==state){for(const g of world.children)g.userData.line.material.color.setHex(g.userData.state===state||g.userData.state===selectedState?0xffe2a0:0xd4e1ef);hovered=state;}tooltip.hidden=!state;renderer.domElement.style.cursor=state?'pointer':'grab';if(state){const model=explorerModel(roster,evidence,chamber,state);tooltip.textContent=state+' · '+model.capacity+' '+ '全部席位'+' · '+'关键席位'+' '+model.keySeats.length;tooltip.style.left=Math.min(e.clientX-rect.left+12,rect.width-200)+'px';tooltip.style.top=Math.max(4,e.clientY-rect.top-38)+'px';}});renderer.domElement.addEventListener('pointerleave',()=>{tooltip.hidden=true;});renderer.domElement.addEventListener('pointerup',e=>{if(!gesture.end(e.pointerId,e.clientX,e.clientY))return;const rect=canvas.getBoundingClientRect(),ray=new T.Raycaster();ray.setFromCamera(new T.Vector2((e.clientX-rect.left)/rect.width*2-1,1-(e.clientY-rect.top)/rect.height*2),camera);const district=ray.intersectObjects(districtLayer?.children.filter(o=>o.isMesh)||[])[0];if(district){onSeat(roster.seats.find(s=>s.seatId===district.object.userData.districtSeat));return;}const hit=ray.intersectObjects(picks)[0];if(hit)selectState(hit.object.userData.state);});
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;new ResizeObserver(()=>{if(!canvas.clientWidth||!canvas.clientHeight)return;camera.aspect=canvas.clientWidth/canvas.clientHeight;camera.updateProjectionMatrix();renderer.setSize(canvas.clientWidth,canvas.clientHeight);reset();}).observe(canvas);new IntersectionObserver(entries=>visible=entries[0].isIntersecting).observe(canvas);function tick(){requestAnimationFrame(tick);if(!visible)return;if(cameraGoal){camera.position.lerp(cameraGoal.pos,reduced?1:.12);controls.target.lerp(cameraGoal.target,reduced?1:.12);if(camera.position.distanceTo(cameraGoal.pos)<.01)cameraGoal=null;}controls.update();scene.traverse(o=>{if(o.isSprite&&o.userData.labelSize&&!o.userData.screenSize){const distance=camera.position.distanceTo(o.getWorldPosition(new T.Vector3())),scale=Math.min(1,distance*.026);o.scale.set(o.userData.labelSize[0]*scale,o.userData.labelSize[1]*scale,1);}});renderer.render(scene,camera);}draw();reset();requestAnimationFrame(tick);
 }catch(error){canvas.dataset.renderError=error.message;canvas.innerHTML='<div class="map-fallback">州地图使用下方州选择与席位列表</div>';canvas.dataset.renderer='accessible-list';renderer=null;}
 host.querySelector('#map-baseline').onchange=e=>{baseMode=e.target.value;host.querySelector('#map-base-label').textContent=baseLabel()+' · 底层';selectState(selectedState,false);};select.onchange=()=>selectState(select.value);host.querySelector('#map-reset').onclick=()=>selectState(null);host.querySelector('#map-top').onclick=()=>{if(!renderer)return;const d=camera.position.distanceTo(controls.target);cameraGoal={target:controls.target.clone(),pos:controls.target.clone().add(new T.Vector3(0,d,.1))};};for(const [id,scale]of [['map-plus',.8],['map-minus',1.25]])host.querySelector('#'+id).onclick=()=>{if(!renderer)return;cameraGoal=null;camera.position.sub(controls.target).multiplyScalar(scale).add(controls.target);};if(!renderer)for(const id of ['map-top','map-plus','map-minus'])host.querySelector('#'+id).disabled=true;describe(null);
 return {update(next,critical=false){chamber=next;keyOnly=critical;selectState(selectedState,false);},selectState};
}
